                             "content":  "Find the missing number in a sequence from 1 to N.\n\n Medium\n 50 XP\n\n 19 hours left\n\n Solve the Problem\n\n WEEKLY017\n\n n = int(input())\nnumbers = [int(input()) for _ in range(n - 1)]\n\n# Find and print the missing number\n\n Subscribe to Weekly Practice Problem\n Get the latest coding practice problem delivered to your inbox every week.\n\n Subscribe\n\nfunction showLangSelector() {\n var _opener = document.activeElement;\n var modal = document.createElement(\u0027div\u0027);\n modal.style.cssText = \u0027position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.7);display:flex;align-items:center;justify-content:center;z-index:10000\u0027;\n modal.setAttribute(\u0027role\u0027, \u0027dialog\u0027);\n modal.setAttribute(\u0027aria-modal\u0027, \u0027true\u0027);\n modal.setAttribute(\u0027aria-label\u0027, \u0027Select a language\u0027);\n function closeLangModal() {\n if (modal.parentNode) document.body.removeChild(modal);\n document.removeEventListener(\u0027keydown\u0027, onLangKey);\n if (_opener \u0026\u0026 typeof _opener.focus === \u0027function\u0027) _opener.focus();\n }\n function onLangKey(e) {\n if (e.key === \u0027Escape\u0027 || e.keyCode === 27) { closeLangModal(); return; }\n if (e.key !== \u0027Tab\u0027 \u0026\u0026 e.keyCode !== 9) return;\n var f = modal.querySelectorAll(\u0027a[href], button:not([disabled])\u0027);\n if (!f.length) return;\n var first = f[0], last = f[f.length - 1];\n if (e.shiftKey \u0026\u0026 document.activeElement === first) { e.preventDefault(); last.focus(); }\n else if (!e.shiftKey \u0026\u0026 document.activeElement === last) { e.preventDefault(); first.focus(); }\n }\n modal.onclick = function(e) { if(e.target === modal) closeLangModal(); };\n document.addEventListener(\u0027keydown\u0027, onLangKey);\n\n var box = document.createElement(\u0027div\u0027);\n box.style.cssText = \u0027background:#fff;border-radius:8px;padding:32px;max-width:600px;width:90%;max-height:80vh;overflow-y:auto\u0027;\n box.innerHTML = \u0027",
